 <div class="stagia-kpi-card"><div><span>STAGES</span><strong id="statTotal">0</strong><small>Stages suivis</small></div><div class="stagia-kpi-icon kpi-blue"><i class="bi bi-briefcase"></i></div></div>
 <div class="stagia-kpi-card"><div><span>EN ATTENTE</span><strong id="statPending">0</strong><small>À examiner</small></div><div class="stagia-kpi-icon kpi-orange"><i class="bi bi-hourglass-split"></i></div></div>
 <div class="stagia-kpi-card"><div><span>ACCEPTÉES</span><strong id="statAccepted">0</strong><small>Décisions favorables</small></div><div class="stagia-kpi-icon kpi-green"><i class="bi bi-check-circle"></i></div></div>
 <div class="stagia-kpi-card"><div><span>REJETÉES</span><strong id="statRejected">0</strong><small>À corriger</small></div><div class="stagia-kpi-icon kpi-red"><i class="bi bi-x-circle"></i></div></div>
