</main>
<div class="modal fade" id="justificationModal" tabindex="-1"><div class="modal-dialog modal-lg"><form class="modal-content" id="form" enctype="multipart/form-data"><div class="modal-header"><div><h5 class="modal-title">Justifier la situation du stage</h5><small id="modalStage" class="text-muted"></small></div><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body">
 <input type="hidden" name="assignment_id" id="assignmentId"><input type="hidden" name="type_situation" id="typeSituation">
 <div class="alert alert-light border" id="situationText"></div>
 <label class="form-label">Motif *</label><select class="form-select mb-3" name="motif" id="reason" required></select>
 <label class="form-label">Explication</label><textarea class="form-control mb-3" name="explication" id="explanation" rows="4" maxlength="4000" placeholder="Précisez les circonstances"></textarea>
 <label class="form-label">Document justificatif facultatif</label><input class="form-control" type="file" name="document" accept="application/pdf,image/jpeg,image/png"><small class="text-muted">PDF, JPG ou PNG — 8 Mo maximum. Un nouveau document remplace l’ancien.</small>
 </div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Annuler</button><button class="btn btn-primary-stagia" id="submitBtn"><i class="bi bi-send me-1"></i>Envoyer</button></div></form></div></div>
<script>
const BASE='<?=BASE_URL?>',CSRF='<?=htmlspecialchars($_SESSION['csrf'],ENT_QUOTES)?>';let items=[],labels={};const $=id=>document.getElementById(id),modal=new bootstrap.Modal($('justificationModal'));
const esc=v=>STAGIA.escape(String(v??'')),dateFr=v=>v?new Date(String(v).substring(0,10)+'T00:00:00').toLocaleDateString('fr-FR'):'-';
async function request(url,options={}){const r=await fetch(BASE+url,{credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'},...options});const j=await r.json();if(!j.success)throw new Error(j.message||'Erreur');return j;}
function badge(s){return s==='ACCEPTEE'?'<span class="badge bg-success">Acceptée</span>':s==='REJETEE'?'<span class="badge bg-danger">Rejetée</span>':s==='EN_ATTENTE'?'<span class="badge bg-warning text-dark">En attente</span>':'<span class="badge bg-secondary">Non envoyée</span>';}
function render(){const q=$('search').value.toLowerCase(),status=$('status').value;const list=items.filter(x=>(!status||x.justification_status===status)&&[x.campaign_code,x.campaign_title,x.host_name,x.unit_name].join(' ').toLowerCase().includes(q));
 $('list').innerHTML=list.length?list.map(x=>`<article class="border rounded-3 p-3 mb-3"><div class="d-flex flex-wrap justify-content-between gap-3"><div><div class="d-flex gap-2 align-items-center flex-wrap"><strong>${esc(x.campaign_code)} — ${esc(x.campaign_title)}</strong>${badge(x.justification_status)}</div><div class="text-muted small mt-1">${esc(x.host_name||'-')} · ${esc(x.unit_name||'-')} · ${dateFr(x.date_debut)} au ${dateFr(x.date_fin)}</div><div class="small mt-2">Situation : <strong>${esc(x.situation)}</strong> · Traces de suivi : ${Number(x.trace_count||0)}</div>${x.justification_reason?`<div class="mt-2"><strong>Motif :</strong> ${esc(x.reason_label)}</div>`:''}${x.decision_commentaire?`<div class="alert alert-light border mt-2 mb-0"><strong>Décision :</strong> ${esc(x.decision_commentaire)}</div>`:''}</div><div class="d-flex gap-2 align-items-start flex-wrap">${x.has_document?`<a class="btn btn-outline-secondary btn-sm" target="_blank" href="${BASE}/actions/stages/student-stage-justification-file.php?token=${encodeURIComponent(x.justification_uuid)}"><i class="bi bi-paperclip"></i> Document</a>`:''}${x.can_justify?`<button class="btn btn-primary-stagia btn-sm" onclick="openForm(${Number(x.assignment_id)})">${x.justification_id?'Modifier / renvoyer':'Justifier'}</button>`:''}</div></div></article>`).join(''):'<div class="text-center py-5 text-muted">Aucun stage ne correspond aux filtres.</div>';}
async function load(){try{const r=await request('/actions/stages/student-stage-justification-list.php');items=r.data.items||[];labels=r.data.reason_labels||{};const s=r.data.stats||{};$('statTotal').textContent=s.total||0;$('statPending').textContent=s.EN_ATTENTE||0;$('statAccepted').textContent=s.ACCEPTEE||0;$('statRejected').textContent=s.REJETEE||0;render();}catch(e){$('list').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`;}}
window.openForm=id=>{const x=items.find(v=>Number(v.assignment_id)===Number(id));if(!x)return;$('form').reset();$('assignmentId').value=x.assignment_id;$('typeSituation').value=x.allowed_type;$('modalStage').textContent=(x.campaign_code||'')+' — '+(x.host_name||'');$('situationText').textContent=x.allowed_type==='INTERRUPTION'?'Des traces de suivi existent : la justification sera enregistrée comme interruption.':'Aucune trace de suivi : la justification sera enregistrée comme non-démarrage.';$('reason').innerHTML=Object.entries(labels).map(([v,l])=>`<option value="${esc(v)}">${esc(l)}</option>`).join('');$('reason').value=x.justification_reason||'MALADIE_INDISPONIBILITE';$('explanation').value=x.justification_explanation||'';modal.show();};
$('form').addEventListener('submit',async e=>{e.preventDefault();const b=$('submitBtn');b.disabled=true;try{const fd=new FormData(e.currentTarget);fd.append('csrf',CSRF);const r=await request('/actions/stages/student-stage-justification-save.php',{method:'POST',body:fd});modal.hide();STAGIA.toast(r.message||'Justification envoyée.','success');await load();}catch(err){STAGIA.toast(err.message,'danger');}finally{b.disabled=false;}});$('search').addEventListener('input',render);$('status').addEventListener('change',render);load();
</script>
